from datetime import datetime


def build_moment_context(parts):
    if not isinstance(parts, (list, tuple)):
        raise TypeError("parts must be a sequence")
    if len(parts) != 6:
        raise TypeError("parts must contain six values")
    if any(isinstance(value, bool) or not isinstance(value, int) for value in parts):
        raise TypeError("date parts must be integers")

    try:
        moment = datetime(*parts)
    except ValueError as exc:
        raise ValueError("invalid date or time") from exc

    display_moment = (
        f"{moment.year}-{moment.month}-{moment.day} "
        f"{moment.hour}:{moment.minute}:{moment.second}"
    )
    return {"display_moment": display_moment}

